#include <iostream>
#include <cstring>
#include <string_view>

int main() {
    const char s1[] = "The value is 3.14159";
    const char allowed[] = "aehi lsTuv";

    // Using std::strspn
    std::size_t span_len = std::strspn(s1, allowed);
    std::cout << "strspn span: " << span_len << "\n";

    // Using std::strstr
    const char text[] = "abcdefabcdef";
    const char target[] = "def";
    const char *found = std::strstr(text, target);
    if (found != nullptr) {
        std::cout << "strstr remainder: " << found << "\n";
    }

    // Modern C++17 string_view equivalent
    std::string_view sv{text};
    auto pos = sv.find(target);
    if (pos != std::string_view::npos) {
        std::cout << "string_view pos: " << pos << "\n";
    }
    return 0;
}

#include <iostream>
#include <cstring>

int main() {
    // Must be a mutable char array, NEVER a string literal (CERT STR06-C)
    char sentence[] = "This is a sentence with 7 tokens";

    std::cout << "Original before strtok: " << sentence << "\n";
    std::cout << "Tokens:\n";

    char *tokenPtr = std::strtok(sentence, " ");
    while (tokenPtr != nullptr) {
        std::cout << tokenPtr << "\n";
        tokenPtr = std::strtok(nullptr, " ");
    }

    // Notice sentence[4] was replaced by '\0'
    std::cout << "First word remaining in buffer: " << sentence << "\n";
    return 0;
}

#include <iostream>
#include <cstring>

int main() {
    // 1. memcpy between disjoint buffers
    char src[] = "Copy this string";
    char dst[17];
    std::memcpy(dst, src, sizeof(src));
    std::cout << "dst after memcpy: " << dst << "\n";

    // 2. memset to reset memory
    char buffer[10];
    std::memset(buffer, 'A', 5);
    buffer[5] = '\0';
    std::cout << "buffer after memset: " << buffer << "\n";

    // 3. memmove on overlapping regions
    char overlap_str[] = "Home Sweet Home";
    // Shift 10 characters starting at index 5 ("Sweet Home") to index 0
    std::memmove(overlap_str, &overlap_str[5], 10);
    std::cout << "overlap_str after memmove: " << overlap_str << "\n";
    return 0;
}
